      "path": "test/repeat.test.js",
      "content": "import assert from \"node:assert/strict\";\nimport { describe, it } from \"node:test\";\nimport {\n  callKey,\n  canonicalize,\n  nextChain,\n  readThreshold,\n  toPatterns,\n  tracked,\n  wildcardToRegExp,\n} from \"../lib/repeat.js\";\n\ndescribe(\"readThreshold\", () => {\n  it(\"accepts integers >= 2\", () => {\n    assert.equal(readThreshold(6), 6);\n    assert.equal(readThreshold(\"8\"), 8);\n  });\n\n  it(\"falls back to 6 when the value is missing or invalid\", () => {\n    assert.equal(readThreshold(undefined), 6);\n    assert.equal(readThreshold(1), 6);\n    assert.equal(readThreshold(1.5), 6);\n  });\n});\n\ndescribe(\"wildcardToRegExp\", () => {\n  it(\"matches a literal tool name\", () => {\n    assert.equal(wildcardToRegExp(\"bash\").test(\"bash\"), true);\n    assert.equal(wildcardToRegExp(\"bash\").test(\"bash2\"), false);\n  });\n\n  it(\"treats * as a glob\", () => {\n    const re = wildcardToRegExp(\"job_*\");\n    assert.equal(re.test(\"job_output\"), true);\n    assert.equal(re.test(\"net_doctor\"), false);\n  });\n});\n\ndescribe(\"tracked\", () => {\n  it(\"skips excluded names\", () => {\n    const exclude = toPatterns([\"job_output\", \"job_*\"]);\n    assert.equal(tracked(\"job_list\", [], exclude), false);\n    assert.equal(tracked(\"bash\", [], exclude), true);\n  });\n\n  it(\"limits tracking to include when set\", () => {\n    const include = toPatterns([\"bash\", \"read_*\"]);\n    assert.equal(tracked(\"bash\", include, []), true);\n    assert.equal(tracked(\"read_file\", include, []), true);\n    assert.equal(tracked(\"net_doctor\", include, []), false);\n  });\n});\n\ndescribe(\"canonicalize\", () => {\n  it(\"sorts object keys so argument order does not reset the streak\", () => {\n    assert.equal(\n      canonicalize({ b: 1, a: 2 }),\n      canonicalize({ a: 2, b: 1 }),\n    );\n  });\n});\n\ndescribe(\"callKey\", () => {\n  it(\"includes the tool name and canonical arguments\", () => {\n    const a = callKey({ name: \"bash\", arguments: { command: \"ls\", cwd: \".\" } });\n    const b = callKey({ name: \"bash\", arguments: { cwd: \".\", command: \"ls\" } });\n    const c = callKey({ name: \"bash\", arguments: { command: \"pwd\" } });\n    assert.equal(a, b);\n    assert.notEqual(a, c);\n  });\n\n  it(\"treats missing arguments as an empty object\", () => {\n    assert.equal(\n      callKey({ name: \"net_doctor\" }),\n      callKey({ name: \"net_doctor\", arguments: {} }),\n    );\n  });\n});\n\ndescribe(\"nextChain\", () => {\n  it(\"increments only while the key stays the same\", () => {\n    const first = nextChain(undefined, \"a\");\n    const second = nextChain(first, \"a\");\n    const reset = nextChain(second, \"b\");\n    assert.deepEqual(first, { key: \"a\", count: 1 });\n    assert.deepEqual(second, { key: \"a\", count: 2 });\n    assert.deepEqual(reset, { key: \"b\", count: 1 });\n  });\n});\n"
    },
    {
      "path": "test/apply.test.js",
      "content": "import assert from \"node:assert/strict\";\nimport { describe, it } from \"node:test\";\nimport { apply } from \"../index.js\";\n\nfunction mockCtx() {\n  const guards = [];\n  const handlers = {};\n  return {\n    tools: {\n      guard(fn) {\n        guards.push(fn);\n      },\n    },\n    on(name, fn) {\n      handlers[name] = fn;\n    },\n    guards,\n    handlers,\n  };\n}\n\nfunction call(agent, name, args) {\n  return { agent, name, arguments: args };\n}\n\ndescribe(\"apply\", () => {\n  it(\"blocks the call after the threshold of identical tools\", () => {\n    const ctx = mockCtx();\n    apply(ctx, { threshold: 2, exclude: [] });\n    const agent = {};\n    const guard = ctx.guards[0];\n    assert.equal(guard(call(agent, \"bash\", { command: \"ls\" })), undefined);\n    assert.equal(guard(call(agent, \"bash\", { command: \"ls\" })), undefined);\n    assert.match(guard(call(agent, \"bash\", { command: \"ls\" })), /blocked bash after 2/);\n  });\n\n  it(\"resets the streak after a real user message\", () => {\n    const ctx = mockCtx();\n    apply(ctx, { threshold: 2, exclude: [] });\n    const agent = {};\n    const guard = ctx.guards[0];\n    assert.equal(guard(call(agent, \"bash\", { command: \"ls\" })), undefined);\n    assert.equal(guard(call(agent, \"bash\", { command: \"ls\" })), undefined);\n    ctx.handlers[\"agent/pre-step\"]({\n      agent,\n      messages: [{ source: { kind: \"user\" } }],\n    }, () => {});\n    assert.equal(guard(call(agent, \"bash\", { command: \"ls\" })), undefined);\n  });\n\n  it(\"does not install a guard when disabled\", () => {\n    const ctx = mockCtx();\n    apply(ctx, { enabled: false, threshold: 6 });\n    assert.equal(ctx.guards.length, 0);\n  });\n\n  it(\"loads with the default threshold when config omits it\", () => {\n    const ctx = mockCtx();\n    apply(ctx, { exclude: [] });\n    assert.equal(ctx.guards.length, 1);\n  });\n});\n"
    },
